<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {ArrowLeft,Film,RefreshCw,Square,Download,ArrowUpRight} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document} from '../domain/local-contract'
import type {MediaProvider,LocalAsset} from './contract'
import {mediaModel} from './runtime'
import type {VideoRecord,VideoDraft} from './video-contract'
import {videoDraft,prepareVideo,executeVideo,refreshVideo,stopVideo,saveVideo,recoverVideo,videoPending,cancelRemoteVideo} from './video-runtime'
import {downloadAsset} from './assets'
import AssetView from './AssetView.vue'
import Sheet from '../components/Sheet.vue'
const store=useLocal(),route=useRoute(),router=useRouter(),draft=ref<Document<VideoDraft>|null>(null),prompt=ref(''),reference=ref(''),duration=ref(5),ratio=ref('1280:720'),provider=ref<Document<MediaProvider>|null>(null),records=ref<Document<VideoRecord>[]>([]),assets=ref<Document<LocalAsset>[]>([]),selected=ref(''),error=ref(''),busy=ref(false),dirty=ref(false),cancelConfirm=ref(false)
const record=computed(()=>records.value.find(row=>row.id===selected.value)||null),output=computed(()=>assets.value.find(row=>row.id===record.value?.value.outputAssetId)||null),references=computed(()=>assets.value.filter(row=>!row.value.retired&&['image/png','image/jpeg','image/webp'].includes(row.value.mime))),estimate=computed(()=>{const rate=provider.value?.value.videoCapabilities?.creditsPerSecond;return rate===null||rate===undefined?null:rate*duration.value}),labels={queued:'待开始',submitting:'正在提交',submitted:'制作中',querying:'正在查看原任务',saved:'已保存',failed:'未完成',unknown:'响应未确认',cancelled:'已停止',persistence_failed:'等待保存'}
let disposed=false,loadEpoch=0,editVersion=0,queue=Promise.resolve(),poll:ReturnType<typeof setTimeout>|null=null,pollStarted=0;const lifecycle=new AbortController()
const current=(vault:typeof store.vault)=>!disposed&&store.vault===vault&&!!vault?.unlocked
async function load(){const vault=store.vault,ticket=++loadEpoch;if(!vault)return;const [all,files]=await Promise.all([vault.list<VideoRecord>('settings'),vault.list<LocalAsset>('asset')]);const jobs:Document<VideoRecord>[]=[];for(const row of all.filter(row=>row.value.assetType==='video-record'))jobs.push(await recoverVideo(vault,row));let model:Document<MediaProvider>|null=null;try{model=await mediaModel(vault,'video')}catch{}if(current(vault)&&ticket===loadEpoch){records.value=jobs.sort((a,b)=>b.value.createdAt.localeCompare(a.value.createdAt));assets.value=files;provider.value=model;if(!selected.value)selected.value=jobs[0]?.id||''}}
function saveDraft(){const value={prompt:prompt.value,referenceId:reference.value||null,duration:duration.value,ratio:ratio.value},version=editVersion;queue=queue.then(async()=>{const vault=store.vault,row=draft.value;if(!vault||!row||!current(vault))return;await vault.commitBundle(crypto.randomUUID(),[{kind:'settings',id:row.id,expectedRevision:row.revision,value:{...row.value,...value}}],lifecycle.signal);if(current(vault)){draft.value=(await vault.read<VideoDraft>(row.id))!;dirty.value=version!==editVersion}}).catch(e=>{if(!disposed){error.value=(e as Error).message;dirty.value=true}});return queue}
function edited(){editVersion++;dirty.value=true;void saveDraft()}
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(async()=>{await saveDraft();return !dirty.value})
function stopPoll(){if(poll)clearTimeout(poll);poll=null}
function schedule(id:string){stopPoll();const vault=store.vault;if(!current(vault)||Date.now()-pollStarted>(provider.value?.value.totalMs||300000))return;poll=setTimeout(async()=>{poll=null;if(disposed||busy.value||!current(vault))return;await query(id,true)},5000)}
async function query(id:string,automatic=false){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';try{const result=await refreshVideo(vault,id);if(!current(vault))return;await load();if(automatic&&result.value.status==='submitted')schedule(id)}catch(e){if(current(vault)){error.value=(e as Error).message;await load().catch(()=>{})}}finally{if(current(vault))busy.value=false}}
async function generate(variant=false){const vault=store.vault,row=draft.value;if(!vault||!row||busy.value)return;busy.value=true;error.value='';stopPoll();try{await saveDraft();if(dirty.value)throw Error('草稿尚未保存');const job=await prepareVideo(vault,{prompt:prompt.value,referenceId:reference.value||null,source:row.value.source,duration:duration.value,ratio:ratio.value,variant,signal:lifecycle.signal});if(!current(vault))return;selected.value=job.id;await load();const submitted=job.value.status==='queued'?await executeVideo(vault,job.id):job;if(!current(vault))return;await load();if(submitted.value.status==='submitted'){pollStarted=Date.now();schedule(job.id)}}catch(e){if(current(vault)){error.value=(e as Error).message;await load().catch(()=>{})}}finally{if(current(vault))busy.value=false}}
async function stop(){const vault=store.vault,row=record.value;if(!vault||!row)return;stopPoll();try{await stopVideo(vault,row.id);if(current(vault))await load()}catch(e){if(current(vault))error.value=(e as Error).message}}
async function saveOnly(){const vault=store.vault,row=record.value;if(!vault||!row||busy.value)return;busy.value=true;try{await saveVideo(vault,row.id);if(current(vault)){error.value='';await load()}}catch(e){if(current(vault))error.value=(e as Error).message}finally{if(current(vault))busy.value=false}}
async function remoteCancel(){const vault=store.vault,row=record.value;if(!vault||!row||busy.value)return;busy.value=true;cancelConfirm.value=false;stopPoll();try{await cancelRemoteVideo(vault,row.id);if(current(vault))await load()}catch(e){if(current(vault)){error.value=(e as Error).message;await load().catch(()=>{})}}finally{if(current(vault))busy.value=false}}
function changed(){void load().catch(e=>{if(!disposed)error.value=(e as Error).message})}
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);window.addEventListener('reader-video-changed',changed);try{const vault=store.vault;if(!vault)return;if(typeof route.query.record==='string'){await load();if(!current(vault))return;const wanted=records.value.find(row=>row.id===route.query.record);if(!wanted)throw Error('这份视频记录已删除或无法打开');selected.value=wanted.id;return}const id=typeof route.query.draft==='string'?route.query.draft:null;if(!id){const destination=await videoDraft(vault,'',null,null,lifecycle.signal);if(current(vault))await router.replace(destination);return}const row=await vault.read<VideoDraft>(id);if(!row||row.value.assetType!=='video-draft')throw Error('这个视频草稿已失效');if(!current(vault))return;draft.value=row;prompt.value=row.value.prompt;reference.value=row.value.referenceId||'';duration.value=row.value.duration;ratio.value=row.value.ratio;await load()}catch(e){if(!disposed)error.value=(e as Error).message}})
onUnmounted(()=>{disposed=true;lifecycle.abort();stopPoll();window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('reader-video-changed',changed);draft.value=null;prompt.value='';provider.value=null;records.value=[];assets.value=[]})
</script>
<template><section class="final-video-page"><div class="final-page-heading"><div class="final-heading-copy"><RouterLink to="/local/gallery" class="final-text-link"><ArrowLeft :size="17"/>画廊</RouterLink><h1>让画面动起来</h1><RouterLink v-if="!draft" to="/local/video" class="final-text-link">新建视频</RouterLink></div><RouterLink to="/local/settings/media" class="final-text-link">视频通道<ArrowUpRight :size="16"/></RouterLink></div><p v-if="error" class="final-error" role="alert">{{error}}</p><div class="final-video-layout"><form v-if="draft" class="final-video-workbench" @submit.prevent="generate()"><label>画面与动作<textarea v-model="prompt" aria-label="视频描述" rows="6" maxlength="1000" required :disabled="busy" @input="edited" @blur="saveDraft" placeholder="雾气掠过河面，纸船旁的灯轻轻摇晃…"/></label><label>参考画面<select v-model="reference" aria-label="视频参考画面" :disabled="busy" @change="edited"><option value="">从文字开始</option><option v-for="row in references" :key="row.id" :value="row.id">{{row.value.name}}</option></select></label><div class="final-video-options"><label>时长<select v-model.number="duration" aria-label="视频时长" :disabled="busy" @change="edited"><option v-for="seconds in provider?.value.videoCapabilities?.durations||[5,10]" :key="seconds" :value="seconds">{{seconds}} 秒</option></select></label><label>画幅<select v-model="ratio" aria-label="视频画幅" :disabled="busy" @change="edited"><option v-for="size in provider?.value.videoCapabilities?.ratios||['1280:720','720:1280']" :key="size" :value="size">{{size==='1280:720'?'横屏 · 16:9':size==='720:1280'?'竖屏 · 9:16':size}}</option></select></label></div><div class="final-video-estimate"><span>{{dirty?'草稿保存中 · ':''}}{{estimate===null?'估价未提供':'预计 '+estimate+' 积分'}}</span><small v-if="provider">{{provider.value.modelId}}</small></div><RouterLink v-if="!provider" to="/local/settings/media" class="final-text-link">配置独立视频通道</RouterLink><button class="final-primary" :disabled="busy||!draft||!provider||!prompt.trim()"><Film :size="18"/>{{busy?'正在处理…':'开始制作'}}</button><small v-if="draft?.value.source" class="final-subtle">已关联所选故事位置</small></form><div class="final-video-result"><template v-if="record"><div class="final-video-result-heading"><h2>{{labels[record.value.status]}}</h2><span class="final-subtle">{{record.value.duration}} 秒</span></div><AssetView v-if="output" :asset="output" full/><div v-else class="final-video-empty"><Film :size="36"/><span>{{record.value.providerTaskId?'原任务已记录':'从一段文字或一幅画面开始'}}</span></div><p v-if="record.value.error" class="final-subtle" role="status">{{record.value.error}}</p><div class="final-grid-actions"><button v-if="output" @click="store.vault&&downloadAsset(store.vault,output)"><Download :size="17"/>下载原视频</button><button v-if="record.value.providerTaskId&&!record.value.outputAssetId&&!record.value.historical" :disabled="busy" @click="query(record.id)"><RefreshCw :size="17"/>查询原任务</button><button v-if="['queued','submitting','submitted','querying','persistence_failed'].includes(record.value.status)&&!record.value.stopped" @click="stop"><Square :size="17"/>停止等待</button><button v-if="store.vault&&videoPending(store.vault,record.id)" :disabled="busy" @click="saveOnly">只重试保存</button></div><button v-if="record.value.providerTaskId&&!record.value.outputAssetId&&!record.value.remoteCancelAttempted&&!record.value.historical" :disabled="busy" @click="cancelConfirm=true">取消供应商任务</button><details class="final-video-details"><summary>来源与费用</summary><p>{{record.value.configSnapshot.modelId}} · {{record.value.providerTaskId||'尚无供应商任务编号'}}</p><p>配置估价 {{record.value.estimatedCredits??'未提供'}} · 供应商估价 {{record.value.providerEstimate??'未提供'}} · 实际 {{record.value.actualCredits??'未提供'}} 积分</p><p>任务状态 {{record.value.providerStatus||'未确认'}}</p><a v-if="record.value.configSnapshot.videoCapabilities?.pricingSource" :href="record.value.configSnapshot.videoCapabilities.pricingSource" target="_blank" rel="noopener noreferrer" class="final-text-link">价格来源</a><p>{{record.value.prompt}}</p></details></template><div v-else class="final-video-empty"><Film :size="36"/><span>一幅画面，另一种呼吸。</span></div></div></div><section v-if="records.length" class="final-video-history"><h2>制作记录</h2><div class="final-video-history-list"><button v-for="row in records.slice(0,100)" :key="row.id" :aria-pressed="selected===row.id" @click="selected=row.id"><span>{{row.value.prompt.slice(0,80)}}</span><small>{{labels[row.value.status]}} · {{row.value.duration}} 秒</small></button></div></section><Sheet v-if="cancelConfirm" title="取消供应商任务" @close="cancelConfirm=false"><p>Runway 会取消进行中的任务，也可能删除已完成的远端结果。已下载到私人库的素材保留。</p><button class="final-primary" :disabled="busy" @click="remoteCancel">确认取消原任务</button></Sheet></section></template>
<style scoped>.final-video-layout{display:grid;grid-template-columns:minmax(280px,1fr) minmax(0,1.25fr);gap:28px;align-items:start}.final-video-workbench,.final-video-result{background:var(--paper);border:1px solid var(--edge);border-radius:18px;padding:24px;display:grid;gap:20px}.final-video-workbench label{display:grid;gap:10px}.final-video-options{display:grid;grid-template-columns:1fr 1fr;gap:16px}.final-video-estimate,.final-video-result-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;font-size:13px}.final-video-estimate small{color:var(--muted)}.final-video-result h2,.final-video-history h2{font:500 22px var(--font-serif);margin:0}.final-video-empty{display:grid;justify-items:center;align-content:center;gap:18px;min-height:270px;border-radius:12px;background:var(--wash);color:var(--muted)}.final-video-details{font-size:13px;color:var(--muted)}.final-video-details p{overflow-wrap:anywhere;line-height:1.8}.final-video-history{margin-top:36px}.final-video-history-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:16px;margin-top:20px}.final-video-history-list button{display:grid;gap:12px;text-align:left;min-width:0;justify-content:start;overflow-wrap:anywhere}.final-video-history-list button[aria-pressed=true]{border-color:var(--accent);background:var(--accent-soft)}.final-video-history-list small{color:var(--muted);font-size:12px}@media(max-width:850px){.final-video-layout{grid-template-columns:1fr}.final-video-workbench,.final-video-result{padding:20px}.final-video-empty{min-height:200px}}</style>
